    if ( iStatus != XWORK_OK ) return iStatus;
    iStatus = xwork__file_write_size(pFile, pSnapshot->iNextEventSequence);
    if ( iStatus != XWORK_OK ) return iStatus;
    iStatus = xwork__file_write_size(pFile, pSnapshot->iNextArtifactSequence);
    if ( iStatus != XWORK_OK ) return iStatus;
