    iStatus = xwork__file_read_size(pFile, &iValue);
    if ( iStatus != XWORK_OK ) return iStatus;
    pSnapshot->eState = (xwork_run_state)iValue;
    iStatus = xwork__file_read_string(pFile, &pSnapshot->sLastOutputText);
